WITH flagged AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 20 MINUTES THEN 1 ELSE 0 END AS is_new_session FROM device_readings), sessionized AS (SELECT id, device_code, reading_ts, pressure, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT island_id, DATE_TRUNC('DAY', reading_ts) AS activity_day, ROUND(SUM(pressure) / NULLIF(COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END), 0), 2) AS pressure_per_dv_04, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes, STDDEV_SAMP(pressure) AS pressure_stddev, MIN(reading_ts) AS first_reading_ts, APPROX_PERCENTILE(island_id, 0.95) AS island_id_p95 FROM sessionized GROUP BY island_id, DATE_TRUNC('DAY', reading_ts) ORDER BY island_id_p95;
